/**
 * Unit tests for StringUtils.indexOfAny(CharSequence cs, char[] searchChars)
 */
public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;























    @Test
    public void testIndexOfAny_SearchCharsContainsCharInCs() {
        char[] searchChars = {'b', 'a'};
        // 'a' is at index 0, 'b' is at index 1. 
        // The loop iterates through cs first, so it finds 'a' at 0.
        assertEquals(0, StringUtils.indexOfAny("abc", searchChars));
    }
